use std::fs;
use std::io::{self, Write};

// ---- A simple file processor ----
struct FileProcessor {
    input_path: String,
    output_path: String,
    verbose: bool,
}

impl FileProcessor {
    fn new(input_path: String, output_path: String, verbose: bool) -> Self {
        FileProcessor {
            input_path,
            output_path,
            verbose,
        }
    }

    fn process(&self) -> Result<(), Box<dyn std::error::Error>> {
        if self.verbose {
            println!("Reading from: {}", self.input_path);
        }

        // Read input file
        let content = fs::read_to_string(&self.input_path)?;

        if self.verbose {
            println!("Read {} bytes", content.len());
        }

        // Process content
        let processed = self.process_content(&content);

        if self.verbose {
            println!("Writing to: {}", self.output_path);
        }

        // Write output file
        fs::write(&self.output_path, processed)?;

        if self.verbose {
            println!("Done!");
        }

        Ok(())
    }

    fn process_content(&self, content: &str) -> String {
        // Example: Count lines and words
        let lines = content.lines().count();
        let words = content.split_whitespace().count();
        let chars = content.chars().count();

        format!(
            "Line count: {}\nWord count: {}\nCharacter count: {}\n\nOriginal content:\n{}",
            lines, words, chars, content
        )
    }
}

// ---- Using the processor ----
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let processor = FileProcessor::new(
        "input.txt".to_string(),
        "output.txt".to_string(),
        true,
    );

    // Create sample input file
    fs::write("input.txt", "Hello world!\nThis is a test file.")?;

    processor.process()?;

    // Read and display output
    let output = fs::read_to_string("output.txt")?;
    println!("\n=== Output ===\n{}", output);

    Ok(())
}

// ---- Async version with Tokio ----
use tokio::fs as async_fs;

struct AsyncFileProcessor {
    input_path: String,
    output_path: String,
    verbose: bool,
}

impl AsyncFileProcessor {
    async fn process(&self) -> Result<(), Box<dyn std::error::Error>> {
        if self.verbose {
            println!("Reading from: {}", self.input_path);
        }

        let content = async_fs::read_to_string(&self.input_path).await?;

        if self.verbose {
            println!("Read {} bytes", content.len());
        }

        let processed = self.process_content(&content);

        if self.verbose {
            println!("Writing to: {}", self.output_path);
        }

        async_fs::write(&self.output_path, processed).await?;

        if self.verbose {
            println!("Done!");
        }

        Ok(())
    }

    fn process_content(&self, content: &str) -> String {
        // Example: Reverse each line
        content
            .lines()
            .map(|line| line.chars().rev().collect::<String>())
            .collect::<Vec<_>>()
            .join("\n")
    }
}

